insert into public.eras (id, name, start_year, end_year, params, summary) values ('now', 'Atual (2026) — TV em todas as telas', 2020, 2036, $json${"tlePrime":0.45,"digitalEscape":0.35,"noiseSd":1.8,"beta":1.4,"retentionBase":0.4,"priceIndex":1,"socialWeight":0.8,"minuteByMinute":true,"minuteFromYear":2020,"outsideUtil":3.3,"youngOutside":0.7,"cppBase":7000,"universeScale":1,"adMinutesDefault":12,"kidsTV":0.3,"payTvReach":0.25,"costScale":1,"inflation":"baixa","playable_years":[2026],"currency":"Real","currency_note":"Valores em R$ de 2026.","message_format":"WhatsApp, e-mail ou áudio"}$json$::jsonb, 'TV linear ainda grande, mas fragmentada: YouTube e streaming disputam a audiência total (em dez/2024 as plataformas digitais já respondiam por 20,1% do vídeo no Brasil). A TV 3.0 (DTV+) entrou em operação comercial em junho de 2026 no Rio, em São Paulo e em Brasília, liberando interatividade, aplicativo do canal e publicidade segmentada. 2026 é ano de Copa do Mundo e de eleições gerais: HGPE, debates e apuração disputam a grade. Anunciantes compram audiência cross-media (TV + digital). Comunicação por WhatsApp.') on conflict (id) do update set name = excluded.name, start_year = excluded.start_year, end_year = excluded.end_year, params = excluded.params, summary = excluded.summary;
insert into public.era_rules (era_id, rule_key, config, severity, text) values ('now', 'rating_hours', $json${"hours":{"10":null,"12":"20:00","14":"21:00","16":"22:00","18":"23:00","L":null},"fineUntilYear":2015}$json$::jsonb, 'warn', 'Classificação indicativa: livre e 10 anos a qualquer hora; 12 a partir das 20h; 14 a partir das 21h; 16 a partir das 22h; 18 a partir das 23h. O horário é recomendação; descumprir gera pressão pública e regulatória, não multa automática.');
