insert into public.event_templates (id, category, title, trigger, base_prob, options, eras, universe, meta) values ('talento_pede_aumento', 'talento', 'Pedido de aumento após recorde', $json${"subject":"talent","all":[["talent.programRank","lte",2],["talent.ego","gte",65],["talent.monthsLeft","lte",8]]}$json$::jsonb, 0.3, $json$[{"id":"pagar","label":"Pagar os 40%","effects":{"salaryPct":40,"npc":[{"target":"context_talent","mood":20,"loyalty":15},{"target":"comercial","mood":-5}]}},{"id":"negociar_merch","label":"Oferecer 15% + cota de merchandising","effects":{"salaryPct":15,"program":{"target":"context","quality":-3},"npc":[{"target":"context_talent","mood":5},{"target":"comercial","mood":8}]}},{"id":"deixar_sair","label":"Não ceder; deixar ir se quiser","effects":{"talentLeaves":true,"program":{"target":"context","appeal":-15},"npc":[{"target":"presidente","trust":-4}]}}]$json$::jsonb, array['now']::text[], array['real','fictional']::text[], $json${"severity":"medio","tone":"negativo","speaker":"context_talent","scene":"{talent} entrou na sua sala sem bater. \"Diretor, {program} está entre os mais vistos da faixa. Meu empresário acha que 40% de reajuste é o mínimo. A concorrência acha a mesma coisa.\"","default_option":"deixar_sair","blocking":false,"cooldown_weeks":16,"calendar":false,"arc":null}$json$::jsonb);
insert into public.event_templates (id, category, title, trigger, base_prob, options, eras, universe, meta) values ('atriz_adoece', 'talento', 'Protagonista afastada da novela', $json${"subject":"program","all":[["program.group","eq","drama"],["program.isFinite","true"],["program.epsLeft","gte",20],["program.hasTalent","true"]]}$json$::jsonb, 0.06, $json$[{"id":"reescrever","label":"Reescrever o núcleo","effects":{"program":{"target":"context","quality":-2,"mult":0.96,"weeks":4},"cashWeeks":-0.05,"npc":[{"target":"artistico","mood":5}]}},{"id":"substituir","label":"Substituir a atriz","effects":{"program":{"target":"context","appeal":-6,"buzz":6},"reputation":{"critics":-1}}},{"id":"pausar","label":"Pausar e exibir compacto","effects":{"program":{"target":"context","mult":0.85,"weeks":3,"buzz":-6},"npc":[{"target":"comercial","mood":-8}]}}]$json$::jsonb, array['now']::text[], array['real','fictional']::text[], $json${"severity":"grave","tone":"negativo","speaker":"npc_artistico","scene":"Lúcia Prado ligou às 7h: a protagonista de {program} foi afastada por ordem médica por pelo menos um mês. \"Temos capítulos gravados para dez dias. Depois disso, ou reescrevemos, ou substituímos, ou entramos com compacto.\"","default_option":"pausar","blocking":true,"cooldown_weeks":30,"calendar":false,"arc":null}$json$::jsonb);
insert into public.event_templates (id, category, title, trigger, base_prob, options, eras, universe, meta) values ('apresentador_polemica', 'talento', 'Polêmica ao vivo', $json${"subject":"talent","all":[["talent.risk","gte",55],["talent.onAir","true"]]}$json$::jsonb, 0.12, $json$[{"id":"suspender","label":"Suspender por uma semana","effects":{"program":{"target":"context","mult":0.9,"weeks":1},"npc":[{"target":"context_talent","mood":-20,"loyalty":-10},{"target":"juridico","trust":5}],"reputation":{"critics":2,"market":1}}},{"id":"defender","label":"Defender publicamente","effects":{"npc":[{"target":"context_talent","mood":15,"loyalty":10},{"target":"comercial","mood":-10}],"reputation":{"market":-3,"public":1},"program":{"target":"context","buzz":8}}},{"id":"nota","label":"Nota oficial de desculpas","effects":{"npc":[{"target":"context_talent","mood":-5}],"reputation":{"market":1}}}]$json$::jsonb, array['now']::text[], array['real','fictional']::text[], $json${"severity":"medio","tone":"negativo","speaker":"npc_juridico","scene":"Ontem, ao vivo, {talent} fez um comentário que pegou mal. O telefone da Dra. Helena não para: \"Diretor, temos anunciante pedindo explicação e uma associação ameaçando representar contra a emissora.\"","default_option":"nota","blocking":false,"cooldown_weeks":12,"calendar":false,"arc":null}$json$::jsonb);
insert into public.event_templates (id, category, title, trigger, base_prob, options, eras, universe, meta) values ('ator_quer_sair', 'talento', 'Ator quer deixar a novela', $json${"subject":"talent","all":[["talent.mood","lte",-10],["talent.programIsNovela","true"]]}$json$::jsonb, 0.15, $json$[{"id":"liberar","label":"Liberar e matar o personagem","effects":{"program":{"target":"context","buzz":10,"appeal":-5},"npc":[{"target":"context_talent","mood":10},{"target":"artistico","mood":-5}]}},{"id":"aumento","label":"Segurar com aumento","effects":{"salaryPct":20,"npc":[{"target":"context_talent","mood":15,"loyalty":10}]}},{"id":"arco","label":"Pedir ao autor um arco maior","effects":{"program":{"target":"context","quality":2},"npc":[{"target":"context_talent","mood":8},{"target":"artistico","mood":5}]}}]$json$::jsonb, array['now']::text[], array['real','fictional']::text[], $json${"severity":"medio","tone":"negativo","speaker":"context_talent","scene":"{talent} quer sair de {program} antes do fim da trama. \"Recebi um convite para teatro e estou cansado do meu personagem. Ou vocês me dão um arco de verdade, ou eu peço para morrer na história.\"","default_option":"liberar","blocking":false,"cooldown_weeks":20,"calendar":false,"arc":null}$json$::jsonb);
insert into public.event_templates (id, category, title, trigger, base_prob, options, eras, universe, meta) values ('apresentador_doente', 'talento', 'Apresentador fora do ar', $json${"subject":"talent","all":[["talent.onAir","true"],["talent.archetypeIn","in",["apresentador_auditorio","apresentadora_matinal","apresentador_talk","apresentador_policial","apresentador_reality"]]]}$json$::jsonb, 0.05, $json$[{"id":"substituto","label":"Chamar apresentador substituto","effects":{"program":{"target":"context","mult":0.92,"weeks":1}}},{"id":"reprise","label":"Exibir reprise de melhores momentos","effects":{"program":{"target":"context","mult":0.85,"weeks":1},"npc":[{"target":"comercial","mood":-6}]}},{"id":"especial","label":"Montar especial com convidados (custo extra)","effects":{"cashWeeks":-0.04,"program":{"target":"context","mult":0.98,"weeks":1,"buzz":3}}}]$json$::jsonb, array['now']::text[], array['real','fictional']::text[], $json${"severity":"leve","tone":"negativo","speaker":"npc_bia","scene":"Bia trouxe o recado: {talent} está com laringite e não grava esta semana. \"A produção sugeriu três saídas. A Marta só pediu que não seja reprise, porque o cliente pagou por programa inédito.\"","default_option":"reprise","blocking":false,"cooldown_weeks":20,"calendar":false,"arc":null}$json$::jsonb);
insert into public.event_templates (id, category, title, trigger, base_prob, options, eras, universe, meta) values ('talento_assediado', 'concorrencia', 'Assédio da concorrência', $json${"subject":"talent","all":[["talent.monthsLeft","lte",6],["talent.popularity","gte",55]]}$json$::jsonb, 0, $json$[{"id":"cobrir","label":"Cobrir a proposta (+60% de salário)","effects":{"salaryPct":60,"npc":[{"target":"context_talent","mood":15,"loyalty":20},{"target":"comercial","mood":-4}]}},{"id":"contraproposta","label":"Contraproposta de +25% e mais visibilidade","effects":{"salaryPct":25,"program":{"target":"context","buzz":5},"npc":[{"target":"context_talent","mood":5,"loyalty":5}]}},{"id":"deixar_ir","label":"Deixar ir para a concorrência","effects":{"talentLeaves":true,"program":{"target":"context","appeal":-12},"reputation":{"public":-2}}}]$json$::jsonb, array['now']::text[], array['real','fictional']::text[], $json${"severity":"grave","tone":"negativo","speaker":"context_talent","scene":"{talent} pediu uma conversa franca: \"A {rival} me ofereceu o dobro e horário nobre garantido. Gosto daqui, mas preciso ouvir uma proposta sua até sexta.\"","default_option":"deixar_ir","blocking":true,"cooldown_weeks":null,"calendar":true,"arc":null}$json$::jsonb);
