insert into public.event_templates (id, category, title, trigger, base_prob, options, eras, universe, meta) values ('merchandising_excessivo', 'comercial', 'Comercial quer mais merchandising', $json${"subject":"program","all":[["program.merch","lte",1],["program.commercial","gte",60]]}$json$::jsonb, 0.1, $json$[{"id":"aceitar","label":"Aceitar três ações por episódio","effects":{"flag":{"merch_up":true},"program":{"target":"context","commercial":5,"quality":-3},"npc":[{"target":"comercial","mood":10},{"target":"artistico","mood":-8}],"cashWeeks":0.06,"reputation":{"critics":-2}}},{"id":"limitar","label":"Uma ação discreta","effects":{"cashWeeks":0.02,"npc":[{"target":"comercial","mood":3}]}},{"id":"recusar","label":"Recusar","effects":{"npc":[{"target":"comercial","mood":-8},{"target":"artistico","mood":6}]}}]$json$::jsonb, array['now']::text[], array['real','fictional']::text[], $json${"severity":"leve","tone":"neutro","speaker":"npc_comercial","scene":"\"Tenho três clientes querendo ação dentro de {program}\", diz Marta. \"Uma no começo, uma no meio, uma no fim. É dinheiro na mesa.\" Lúcia, do outro lado, revira os olhos.","default_option":"limitar","blocking":false,"cooldown_weeks":12,"calendar":false,"arc":null}$json$::jsonb);
