insert into public.event_templates (id, category, title, trigger, base_prob, options, eras, universe, meta) values ('queda_mercado_publicitario', 'financeiro', 'Mercado publicitário esfria', $json${"subject":"none","all":[]}$json$::jsonb, 0.025, $json$[{"id":"cortar_tabela","label":"Baixar a tabela para segurar clientes","effects":{"priceMult":0.92,"occupancy":{"delta":0.03,"weeks":8}}},{"id":"manter","label":"Manter preço e aguentar","effects":{"occupancy":{"delta":-0.06,"weeks":6}}},{"id":"novos_clientes","label":"Caçar novos anunciantes (agenda)","effects":{"agenda":-3,"occupancy":{"delta":-0.02,"weeks":6},"npc":[{"target":"comercial","mood":6}]}}]$json$::jsonb, array['now']::text[], array['real','fictional']::text[], $json${"severity":"medio","tone":"negativo","speaker":"npc_comercial","scene":"As agências cortaram verbas para o próximo mês. \"Não é só com a gente, diretor, é o mercado inteiro\", diz Marta. \"Mas o presidente vai olhar só para o nosso número.\"","default_option":"manter","blocking":false,"cooldown_weeks":40,"calendar":false,"arc":null}$json$::jsonb);
insert into public.event_templates (id, category, title, trigger, base_prob, options, eras, universe, meta) values ('plantao_capitulo_final', 'jornalismo', 'Plantão em pleno horário nobre', $json${"subject":"program","all":[["program.isPrime","true"],["program.groupIn","in",["drama","reality","variedade"]]]}$json$::jsonb, 0.05, $json$[{"id":"ao_vivo","label":"Entrar ao vivo imediatamente","effects":{"program":{"target":"context","mult":0.95,"weeks":1},"npc":[{"target":"jornalismo","mood":12,"trust":6},{"target":"comercial","mood":-6}],"reputation":{"critics":2,"public":1}}},{"id":"rodape","label":"Rodapé na tela e plantão no intervalo","effects":{"npc":[{"target":"jornalismo","mood":2}]}},{"id":"esperar","label":"Esperar o fim do programa","effects":{"npc":[{"target":"jornalismo","mood":-12,"trust":-6}],"reputation":{"critics":-2}}}]$json$::jsonb, array['now']::text[], array['real','fictional']::text[], $json${"severity":"medio","tone":"neutro","speaker":"npc_jornalismo","scene":"Henrique invadiu a sala de controle: \"Fato grave em Brasília. Precisamos entrar com plantão agora, no meio de {program}.\" Marta, ao telefone, implora para esperar o intervalo.","default_option":"rodape","blocking":false,"cooldown_weeks":16,"calendar":false,"arc":null}$json$::jsonb);
insert into public.event_templates (id, category, title, trigger, base_prob, options, eras, universe, meta) values ('jornalismo_quer_espaco', 'jornalismo', 'Jornalismo quer mais espaço', $json${"subject":"none","all":[["npc.jornalismo.mood","lte",10]]}$json$::jsonb, 0.08, $json$[{"id":"aceitar","label":"Prometer ampliar na próxima temporada","effects":{"flag":{"promessa_jornalismo":true},"npc":[{"target":"jornalismo","mood":12,"trust":5}],"delayed":{"inWeeks":12,"effects":{"npc":[{"target":"jornalismo","mood":-15,"trust":-10}]},"note":"Henrique cobra a promessa de mais espaço não cumprida"}}},{"id":"verba","label":"Dar verba para reportagens especiais","effects":{"cashWeeks":-0.04,"npc":[{"target":"jornalismo","mood":8}],"reputation":{"critics":1}}},{"id":"negar","label":"Negar","effects":{"npc":[{"target":"jornalismo","mood":-10,"trust":-4}]}}]$json$::jsonb, array['now']::text[], array['real','fictional']::text[], $json${"severity":"leve","tone":"neutro","speaker":"npc_jornalismo","scene":"\"Estamos encolhendo, diretor\", diz Henrique. \"Quero mais quinze minutos no telejornal da noite e um programa de entrevistas. Sem isso, a redação perde gente.\"","default_option":"negar","blocking":false,"cooldown_weeks":20,"calendar":false,"arc":null}$json$::jsonb);
