insert into public.event_templates (id, category, title, trigger, base_prob, options, eras, universe, meta) values ('arc_venda_1', 'arco', 'Rumor de venda da emissora', $json${"subject":"none","all":[]}$json$::jsonb, 0, $json$[{"id":"investigar","label":"Sondar o presidente","effects":{"agenda":-2,"npc":[{"target":"presidente","trust":-2}],"arcAdvance":"venda_emissora"}},{"id":"ignorar","label":"Fingir que não ouviu","effects":{"arcAdvance":"venda_emissora"}}]$json$::jsonb, array['now']::text[], array['real','fictional']::text[], $json${"severity":"medio","tone":"neutro","speaker":"npc_bia","scene":"Bia ouviu no elevador: um grupo estrangeiro estaria interessado em comprar a emissora. O presidente nega, mas cancelou a reunião de sexta.","default_option":"ignorar","blocking":false,"cooldown_weeks":null,"calendar":true,"arc":{"key":"venda_emissora","stage":0}}$json$::jsonb);
insert into public.event_templates (id, category, title, trigger, base_prob, options, eras, universe, meta) values ('arc_venda_2', 'arco', 'A proposta chegou', $json${"subject":"none","all":[]}$json$::jsonb, 0, $json$[{"id":"mostrar","label":"Prometer números fortes","effects":{"flag":{"venda_meta":true},"npc":[{"target":"presidente","trust":5,"patience":-10}],"arcAdvance":"venda_emissora"}},{"id":"cautela","label":"Pedir cautela","effects":{"npc":[{"target":"presidente","trust":-3}],"arcAdvance":"venda_emissora"}}]$json$::jsonb, array['now']::text[], array['real','fictional']::text[], $json${"severity":"grave","tone":"neutro","speaker":"npc_presidente","scene":"O presidente admite, a portas fechadas: há uma proposta. \"Eles querem ver a grade e os números do próximo trimestre antes de fechar. Não me envergonhe.\"","default_option":"cautela","blocking":false,"cooldown_weeks":null,"calendar":true,"arc":{"key":"venda_emissora","stage":1}}$json$::jsonb);
insert into public.event_templates (id, category, title, trigger, base_prob, options, eras, universe, meta) values ('arc_venda_3', 'arco', 'Due diligence', $json${"subject":"none","all":[]}$json$::jsonb, 0, $json$[{"id":"antecipar","label":"Antecipar cotas","effects":{"cashWeeks":0.08,"delayed":{"inWeeks":8,"effects":{"cashWeeks":-0.1},"note":"O caixa sente a antecipação de cotas"},"arcAdvance":"venda_emissora"}},{"id":"limpo","label":"Mostrar tudo como está","effects":{"npc":[{"target":"juridico","trust":6}],"reputation":{"market":2},"arcAdvance":"venda_emissora"}}]$json$::jsonb, array['now']::text[], array['real','fictional']::text[], $json${"severity":"grave","tone":"neutro","speaker":"npc_comercial","scene":"Os auditores do comprador estão em todas as salas. Marta sugere inflar o faturamento do mês com antecipação de cotas; a Dra. Helena desaconselha.","default_option":"limpo","blocking":false,"cooldown_weeks":null,"calendar":true,"arc":{"key":"venda_emissora","stage":2}}$json$::jsonb);
insert into public.event_templates (id, category, title, trigger, base_prob, options, eras, universe, meta) values ('arc_venda_4', 'arco', 'O desfecho da venda', $json${"subject":"none","all":[]}$json$::jsonb, 0, $json$[{"id":"ok","label":"Seguir em frente","effects":{"npc":[{"target":"presidente","mood":5}],"arcEnd":"venda_emissora"}}]$json$::jsonb, array['now']::text[], array['real','fictional']::text[], $json${"severity":"medio","tone":"neutro","speaker":"npc_presidente","scene":"O negócio não saiu: o comprador desistiu na última hora. O presidente, aliviado ou frustrado, ninguém sabe, avisa que nada muda. Por enquanto.","default_option":"ok","blocking":false,"cooldown_weeks":null,"calendar":true,"arc":{"key":"venda_emissora","stage":3}}$json$::jsonb);
insert into public.event_templates (id, category, title, trigger, base_prob, options, eras, universe, meta) values ('arc_sucessao_1', 'arco', 'O presidente se afasta', $json${"subject":"none","all":[]}$json$::jsonb, 0, $json$[{"id":"visitar","label":"Visitar o presidente (agenda)","effects":{"agenda":-3,"npc":[{"target":"presidente","trust":8,"mood":10}],"arcAdvance":"sucessao_presidente"}},{"id":"trabalhar","label":"Focar no trabalho","effects":{"arcAdvance":"sucessao_presidente"}}]$json$::jsonb, array['now']::text[], array['real','fictional']::text[], $json${"severity":"medio","tone":"neutro","speaker":"npc_bia","scene":"O presidente foi internado para exames. \"Nada grave\", diz o comunicado. Os corredores, porém, só falam de quem vai mandar se ele não voltar.","default_option":"trabalhar","blocking":false,"cooldown_weeks":null,"calendar":true,"arc":{"key":"sucessao_presidente","stage":0}}$json$::jsonb);
insert into public.event_templates (id, category, title, trigger, base_prob, options, eras, universe, meta) values ('arc_sucessao_2', 'arco', 'Herdeiros em disputa', $json${"subject":"none","all":[]}$json$::jsonb, 0, $json$[{"id":"filha","label":"Apoiar a filha","effects":{"flag":{"sucessor":"filha"},"arcAdvance":"sucessao_presidente"}},{"id":"genro","label":"Apoiar o genro","effects":{"flag":{"sucessor":"genro"},"arcAdvance":"sucessao_presidente"}},{"id":"neutro","label":"Ficar neutro","effects":{"flag":{"sucessor":"neutro"},"npc":[{"target":"presidente","trust":-2}],"arcAdvance":"sucessao_presidente"}}]$json$::jsonb, array['now']::text[], array['real','fictional']::text[], $json${"severity":"grave","tone":"neutro","speaker":"npc_bia","scene":"Dois herdeiros disputam a sucessão: a filha, que quer modernizar tudo, e o genro, que quer cortar custos. Os dois pediram seu apoio.","default_option":"neutro","blocking":false,"cooldown_weeks":null,"calendar":true,"arc":{"key":"sucessao_presidente","stage":1}}$json$::jsonb);
insert into public.event_templates (id, category, title, trigger, base_prob, options, eras, universe, meta) values ('arc_sucessao_3', 'arco', 'A escolha', $json${"subject":"none","all":[]}$json$::jsonb, 0, $json$[{"id":"ok","label":"Entendido","effects":{"npc":[{"target":"presidente","patience":-10}],"arcAdvance":"sucessao_presidente"}}]$json$::jsonb, array['now']::text[], array['real','fictional']::text[], $json${"severity":"medio","tone":"neutro","speaker":"npc_presidente","scene":"O presidente voltou, mais magro e mais duro. \"Eu escolho quem me sucede. E vou escolher olhando para os números de cada diretoria.\"","default_option":"ok","blocking":false,"cooldown_weeks":null,"calendar":true,"arc":{"key":"sucessao_presidente","stage":2}}$json$::jsonb);
insert into public.event_templates (id, category, title, trigger, base_prob, options, eras, universe, meta) values ('arc_sucessao_4', 'arco', 'Novo comando', $json${"subject":"none","all":[]}$json$::jsonb, 0, $json$[{"id":"ok","label":"Seguir em frente","effects":{"arcEnd":"sucessao_presidente","npc":[{"target":"presidente","mood":5}]}}]$json$::jsonb, array['now']::text[], array['real','fictional']::text[], $json${"severity":"medio","tone":"neutro","speaker":"npc_presidente","scene":"O presidente anunciou que fica mais dois anos e depois passa o bastão. A sucessão ficou para depois, mas todo mundo sabe quem estava de que lado.","default_option":"ok","blocking":false,"cooldown_weeks":null,"calendar":true,"arc":{"key":"sucessao_presidente","stage":3}}$json$::jsonb);
insert into public.event_templates (id, category, title, trigger, base_prob, options, eras, universe, meta) values ('arc_autor_1', 'arco', 'O autor exige mais', $json${"subject":"none","all":[]}$json$::jsonb, 0, $json$[{"id":"ceder","label":"Ceder às exigências","effects":{"cashWeeks":-0.05,"npc":[{"target":"artistico","mood":8}],"arcAdvance":"autor_genial"}},{"id":"limitar","label":"Impor limites","effects":{"npc":[{"target":"artistico","mood":-5}],"arcAdvance":"autor_genial"}}]$json$::jsonb, array['now']::text[], array['real','fictional']::text[], $json${"severity":"medio","tone":"neutro","speaker":"npc_artistico","scene":"O autor da sua novela quer cenário novo, elenco maior e direito de veto sobre a trilha. \"Ele é genial\", diz Lúcia, \"mas está impossível\".","default_option":"limitar","blocking":false,"cooldown_weeks":null,"calendar":true,"arc":{"key":"autor_genial","stage":0}}$json$::jsonb);
insert into public.event_templates (id, category, title, trigger, base_prob, options, eras, universe, meta) values ('arc_autor_2', 'arco', 'Ameaça de abandonar a obra', $json${"subject":"none","all":[]}$json$::jsonb, 0, $json$[{"id":"acalmar","label":"Jantar com o autor (agenda)","effects":{"agenda":-3,"npc":[{"target":"artistico","mood":8}],"arcAdvance":"autor_genial"}},{"id":"substituto","label":"Preparar um substituto","effects":{"npc":[{"target":"artistico","mood":-10}],"arcAdvance":"autor_genial"}}]$json$::jsonb, array['now']::text[], array['real','fictional']::text[], $json${"severity":"grave","tone":"neutro","speaker":"npc_artistico","scene":"O autor ameaça abandonar a novela no meio, \"se continuarem mexendo no meu texto\". A imprensa já sabe.","default_option":"substituto","blocking":false,"cooldown_weeks":null,"calendar":true,"arc":{"key":"autor_genial","stage":1}}$json$::jsonb);
insert into public.event_templates (id, category, title, trigger, base_prob, options, eras, universe, meta) values ('arc_autor_3', 'arco', 'A crise explode', $json${"subject":"none","all":[]}$json$::jsonb, 0, $json$[{"id":"publico","label":"Responder publicamente","effects":{"reputation":{"critics":-2},"npc":[{"target":"presidente","mood":3}],"arcAdvance":"autor_genial"}},{"id":"silencio","label":"Silêncio e diplomacia","effects":{"npc":[{"target":"artistico","mood":4}],"arcAdvance":"autor_genial"}}]$json$::jsonb, array['now']::text[], array['real','fictional']::text[], $json${"severity":"medio","tone":"neutro","speaker":"npc_bia","scene":"O autor deu entrevista dizendo que a emissora \"não merece a obra\". O presidente leu durante o café.","default_option":"silencio","blocking":false,"cooldown_weeks":null,"calendar":true,"arc":{"key":"autor_genial","stage":2}}$json$::jsonb);
insert into public.event_templates (id, category, title, trigger, base_prob, options, eras, universe, meta) values ('arc_autor_4', 'arco', 'A obra final', $json${"subject":"none","all":[]}$json$::jsonb, 0, $json$[{"id":"ok","label":"Celebrar","effects":{"reputation":{"critics":4},"allBuzz":3,"arcEnd":"autor_genial"}}]$json$::jsonb, array['now']::text[], array['real','fictional']::text[], $json${"severity":"leve","tone":"positivo","speaker":"npc_artistico","scene":"Os últimos capítulos chegaram: brilhantes. Lúcia está emocionada. \"Valeu cada dor de cabeça.\"","default_option":"ok","blocking":false,"cooldown_weeks":null,"calendar":true,"arc":{"key":"autor_genial","stage":3}}$json$::jsonb);
insert into public.event_templates (id, category, title, trigger, base_prob, options, eras, universe, meta) values ('arc_domingo_1', 'arco', 'Provocação no domingo', $json${"subject":"none","all":[]}$json$::jsonb, 0, $json$[{"id":"responder","label":"Responder no ar","effects":{"allBuzz":3,"reputation":{"critics":-1},"arcAdvance":"guerra_domingo_arc"}},{"id":"ignorar","label":"Ignorar","effects":{"arcAdvance":"guerra_domingo_arc"}}]$json$::jsonb, array['now']::text[], array['real','fictional']::text[], $json${"severity":"medio","tone":"neutro","speaker":"npc_pesquisa","scene":"O apresentador do domingo da {rival} provocou sua emissora no ar. O público adorou a briga; Caio viu o pico no minuto a minuto.","default_option":"ignorar","blocking":false,"cooldown_weeks":null,"calendar":true,"arc":{"key":"guerra_domingo_arc","stage":0}}$json$::jsonb);
