insert into public.event_templates (id, category, title, trigger, base_prob, options, eras, universe, meta) values ('arc_domingo_3', 'arco', 'Empate técnico', $json${"subject":"none","all":[]}$json$::jsonb, 0, $json$[{"id":"all_in","label":"Apostar tudo no próximo domingo","effects":{"cashWeeks":-0.04,"allBuzz":4,"arcAdvance":"guerra_domingo_arc"}},{"id":"calma","label":"Manter a calma","effects":{"arcAdvance":"guerra_domingo_arc"}}]$json$::jsonb, array['now']::text[], array['real','fictional']::text[], $json${"severity":"medio","tone":"neutro","speaker":"npc_pesquisa","scene":"Domingo passado deu empate técnico na tarde. A imprensa chama de \"a maior guerra da TV\". Todo mundo olha para você.","default_option":"calma","blocking":false,"cooldown_weeks":null,"calendar":true,"arc":{"key":"guerra_domingo_arc","stage":2}}$json$::jsonb);
