insert into public.npc_archetypes (id, role, traits) values ('npc_presidente', 'presidente', $json${"fixed":true,"name":"Dr. Otávio Barreto","title":"Presidente","age":64,"sheet":{"speech_style":["lacônico","autoritário","irônico"],"catchphrases":["Eu não pago você para ter opinião, pago para ter audiência.","Número, diretor. Me traga número."],"main_goal":"liderança, lucro e prestígio pessoal da emissora","secret_goal":"deixar a emissora valorizada para uma venda ou sucessão tranquila","red_line":"ser humilhado publicamente pela concorrência ou pela imprensa","bio":"Dono da emissora há duas décadas. Fala pouco, cobra muito e lembra de tudo."},"mood":0,"trust":55,"loyalty":50,"patience":60}$json$::jsonb);
insert into public.npc_archetypes (id, role, traits) values ('npc_comercial', 'comercial', $json${"fixed":true,"name":"Marta Siqueira","title":"Diretora Comercial","age":47,"sheet":{"speech_style":["direta","pragmática","irônica"],"catchphrases":["Ponto não paga conta, diretor. Cota paga.","Meu cliente não compra prestígio, compra GRP."],"main_goal":"bater a meta anual com folga","secret_goal":"ser promovida a superintendente","red_line":"perder o maior anunciante por decisão artística","bio":"Veio de agência de publicidade. Conhece cada anunciante pelo nome e cada desconto pelo centavo."},"mood":10,"trust":55,"loyalty":60,"patience":50}$json$::jsonb);
insert into public.npc_archetypes (id, role, traits) values ('npc_jornalismo', 'jornalismo', $json${"fixed":true,"name":"Henrique Castello","title":"Diretor de Jornalismo","age":58,"sheet":{"speech_style":["formal","combativo","orgulhoso"],"catchphrases":["Jornalismo não é tapa-buraco.","Credibilidade se perde em um dia e se reconstrói em dez anos."],"main_goal":"proteger os telejornais e a credibilidade da casa","secret_goal":"ganhar um programa de entrevistas próprio no horário nobre","red_line":"ver o telejornal principal rebaixado ou cortado","bio":"Repórter de rua por trinta anos. Ameaça pedir demissão uma vez por trimestre."},"mood":0,"trust":50,"loyalty":55,"patience":45}$json$::jsonb);
insert into public.npc_archetypes (id, role, traits) values ('npc_artistico', 'artistico', $json${"fixed":true,"name":"Lúcia Prado","title":"Diretora Artística","age":52,"sheet":{"speech_style":["passional","eloquente","teimosa"],"catchphrases":["Novela boa não se faz com planilha.","Me dê orçamento e eu te dou prêmio."],"main_goal":"orçamento para novelas e séries de prestígio","secret_goal":"emplacar a novela do autor que ela descobriu","red_line":"ver um projeto autoral cancelado sem chance de estrear","bio":"Diretora de núcleo premiada. Protege autores e elenco como família."},"mood":5,"trust":50,"loyalty":55,"patience":50}$json$::jsonb);
insert into public.npc_archetypes (id, role, traits) values ('npc_pesquisa', 'pesquisa', $json${"fixed":true,"name":"Caio Nakamura","title":"Gerente de Pesquisa","age":34,"sheet":{"speech_style":["analítico","cauteloso","seco"],"catchphrases":["O dado não tem opinião.","Isso está dentro da margem de erro, diretor."],"main_goal":"decisões baseadas em evidência","secret_goal":"montar um núcleo de dados próprio","red_line":"ver números maquiados em reunião","bio":"Estatístico. Prefere gráfico a reunião."},"mood":10,"trust":55,"loyalty":60,"patience":60}$json$::jsonb);
insert into public.npc_archetypes (id, role, traits) values ('npc_bia', 'assistente', $json${"fixed":true,"name":"Bia Ramos","title":"Assistente da Diretoria","age":27,"sheet":{"speech_style":["animada","organizada","fofoqueira"],"catchphrases":["Diretor, posso ser sincera?","Anotei tudo, e ouvi umas coisinhas no corredor."],"main_goal":"ajudar o diretor e crescer na carreira","secret_goal":"virar produtora de programa","red_line":"ser tratada como invisível","bio":"Organiza a agenda, resume a semana e sabe de tudo antes de todo mundo."},"mood":30,"trust":65,"loyalty":70,"patience":70}$json$::jsonb);
